import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    starts = [[] for _ in range(n)]
    p = 2
    for _ in range(m):
        l, r, x = data[p] - 1, data[p + 1] - 1, data[p + 2] - 1
        p += 3
        starts[l].append((r, x))

    inf = n + 1
    # mn[l][x] is the minimum right endpoint of a condition centered at x
    # whose left endpoint is at least l.
    mn = [[inf] * n for _ in range(n + 1)]
    for l in range(n - 1, -1, -1):
        mn[l] = mn[l + 1][:]
        for r, x in starts[l]:
            if r < mn[l][x]:
                mn[l][x] = r

    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD
    invfact = [1] * (n + 1)
    invfact[n] = pow(fact[n], MOD - 2, MOD)
    for i in range(n, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    choose = [[0] * (n + 1) for _ in range(n + 1)]
    for a in range(n + 1):
        for b in range(a + 1):
            choose[a][b] = fact[a] * invfact[b] % MOD * invfact[a - b] % MOD

    dp = [[0] * n for _ in range(n)]
    for length in range(1, n + 1):
        for l in range(n - length + 1):
            r = l + length - 1
            total = 0
            for k in range(l, r + 1):
                if mn[l][k] <= r:
                    continue
                left_size = k - l
                right_size = r - k
                left = dp[l][k - 1] if left_size else 1
                right = dp[k + 1][r] if right_size else 1
                total += choose[length - 1][left_size] * left * right
            dp[l][r] = total % MOD

    print(dp[0][n - 1])

if __name__ == '__main__':
    main()

