import sys
from math import isqrt
MOD=998244353

def primes_upto(n):
    s=[True]*(n+1)
    for i in range(2,isqrt(n)+1):
        if s[i]:
            for j in range(i*i,n+1,i): s[j]=False
    return [i for i in range(2,n+1) if s[i]]

def calc(p, b, N):
    B=sum(b)
    if B==0: return 1
    # State (minimum height, current height); accumulate weight of normalized
    # prefixes, updating all existing heights when a new minimum is reached.
    dp={(0,0):1}
    for d in b:
        nd={}
        steps=(0,) if d==0 else (-d,d)
        for (mn,x),v in dp.items():
            for z in steps:
                y=x+z
                mm=min(mn,y)
                # Previous vertices gain dshift in normalized coordinates.
                shift=mn-mm
                w=v*pow(p,shift,MOD)%MOD
                key=(mm,y)
                nd[key]=(nd.get(key,0)+w)%MOD
        dp=nd
    ans=0
    for (mn,x),v in dp.items():
        # Account for the final vertex and normalize all N vertices.
        ans=(ans+v*pow(p,x-mn,MOD))%MOD
    return ans

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    N=data[0]; A=data[1:]
    ans=1
    for p in primes_upto(max(A)):
        b=[]
        active=False
        for x in A:
            c=0
            while x%p==0:
                x//=p; c+=1
            b.append(c); active |= c>0
        if active:
            ans=ans*calc(p,b,N)%MOD
    print(ans)
main()

