import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:]
    v = max(a)

    phi = list(range(v + 1))
    for p in range(2, v + 1):
        if phi[p] == p:
            for k in range(p, v + 1, p):
                phi[k] -= phi[k] // p

    divisors = [[] for _ in range(v + 1)]
    for d in range(1, v + 1):
        for x in range(d, v + 1, d):
            divisors[x].append(d)

    sums = [0] * (v + 1)
    weight = 1
    answer = 0
    output = []
    for x in a:
        t = 0
        for d in divisors[x]:
            t += phi[d] * sums[d]
        t %= MOD
        answer = (2 * answer + t) % MOD
        output.append(str(answer))
        for d in divisors[x]:
            sums[d] = (sums[d] + weight) % MOD
        weight = weight * 2 % MOD

    sys.stdout.write('\n'.join(output))

if __name__ == '__main__':
    main()

