from typing import List
import heapq

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        starts = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            x, y = sorted((a, b))
            starts[y].append((x, i))

        heap = []  # (-left endpoint, pair index), for pairs whose right endpoint has arrived
        gain = [0] * len(conflictingPairs)
        base = 0

        for r in range(1, n + 1):
            for x, i in starts[r]:
                heapq.heappush(heap, (-x, i))

            if heap:
                topx = -heap[0][0]
                # The second-smallest item in a heap must be one of the root's children.
                secondx = -min(heap[1:3])[0] if len(heap) > 1 else 0
                base += r - topx
                gain[heap[0][1]] += topx - secondx
            else:
                base += r

        return base + max(gain)

