import sys
input=sys.stdin.buffer.readline
N,M,Q=map(int,input().split())
edges=[None]*M
for i in range(M):
    a,b,c=map(int,input().split())
    edges[i]=(a-1,b-1,c)
queries=[]
closed=[False]*M
for _ in range(Q):
    t,*v=map(int,input().split())
    if t==1:
        i=v[0]-1
        closed[i]=True
        queries.append((1,i))
    else:
        queries.append((2,v[0]-1,v[1]-1))

INF=10**30
d=[[INF]*N for _ in range(N)]
for i in range(N):
    d[i][i]=0
for i,(a,b,c) in enumerate(edges):
    if not closed[i]:
        d[a][b]=d[b][a]=c

for k in range(N):
    dk=d[k]
    for i in range(N):
        dik=d[i][k]
        if dik==INF:
            continue
        di=d[i]
        for j in range(N):
            nd=dik+dk[j]
            if nd<di[j]:
                di[j]=nd

answers=[]
for q in reversed(queries):
    if q[0]==2:
        x,y=q[1],q[2]
        z=d[x][y]
        answers.append(-1 if z==INF else z)
    else:
        a,b,w=edges[q[1]]
        da=d[a][:]
        db=d[b][:]
        for i in range(N):
            di=d[i]
            ia=di[a]
            ib=di[b]
            for j in range(N):
                nd1=ia+w+db[j]
                nd2=ib+w+da[j]
                if nd1<nd2:
                    nd=nd1
                else:
                    nd=nd2
                if nd<di[j]:
                    di[j]=nd
print('\n'.join(map(str,reversed(answers))))

