import sys
from math import gcd

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, budget = data[0], data[1]
    machines = []
    pos = 2
    for _ in range(n):
        machines.append(tuple(data[pos:pos + 4]))
        pos += 4

    def feasible(target):
        total_cost = 0
        for a, p, b, q in machines:
            period = b // gcd(a, b)
            max_s = (target + a - 1) // a
            best = 10**30

            for residue in range(min(period, max_s + 1)):
                max_t = (max_s - residue) // period
                for t in (0, max_t):
                    s_count = residue + t * period
                    remaining = max(0, target - a * s_count)
                    t_count = (remaining + b - 1) // b
                    cost = p * s_count + q * t_count
                    if cost < best:
                        best = cost

            total_cost += best
            if total_cost > budget:
                return False
        return True

    low, high = 0, budget * 100 + 1
    while low + 1 < high:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)

if __name__ == '__main__':
    main()

