class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)

        # Binomial coefficients modulo MOD.
        comb = [[0] * (n + 1) for _ in range(n + 1)]
        for i in range(n + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

        # Count numbers strictly below s, grouped by their number of set bits.
        by_ones = [0] * (n + 1)
        ones_in_prefix = 0
        for i, bit in enumerate(s):
            remaining = n - i - 1
            if bit == '1':
                # Make this bit 0; the preceding bits match s, and the suffix is free.
                for total_ones in range(1, n + 1):
                    needed = total_ones - ones_in_prefix
                    if 0 <= needed <= remaining:
                        by_ones[total_ones] = (
                            by_ones[total_ones] + comb[remaining][needed]
                        ) % MOD
                ones_in_prefix += 1

        answer = 0
        for count in range(1, n + 1):
            value = count
            reductions_after_first = 0
            while value != 1:
                value = value.bit_count()
                reductions_after_first += 1
            # An integer with this many set bits needs one additional operation
            # to reach that count from the integer itself.
            if reductions_after_first <= k - 1:
                answer = (answer + by_ones[count]) % MOD

        return answer

