import sys

def solve():
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    graph = [row.decode() for row in data[1:]]

    # Incoming/outgoing neighbors grouped by edge label.
    incoming = [[[] for _ in range(26)] for _ in range(n)]
    outgoing = [[[] for _ in range(26)] for _ in range(n)]
    for i in range(n):
        for j, ch in enumerate(graph[i]):
            if ch != '-':
                c = ord(ch) - ord('a')
                outgoing[i][c].append(j)
                incoming[j][c].append(i)

    dist = [[-1] * n for _ in range(n)]
    queue = []
    # Palindromes of length zero and one are the possible centers.
    for i in range(n):
        dist[i][i] = 0
        queue.append((i, i))
    for i in range(n):
        for j, ch in enumerate(graph[i]):
            if ch != '-' and dist[i][j] == -1:
                dist[i][j] = 1
                queue.append((i, j))

    # For each start vertex, keep a bitmask of as-yet-unreached endpoints.
    all_vertices = (1 << n) - 1
    unvisited = [all_vertices] * n
    for i in range(n):
        for j in range(n):
            if dist[i][j] != -1:
                unvisited[i] &= ~(1 << j)

    head = 0
    while head < len(queue):
        i, j = queue[head]
        head += 1
        new_dist = dist[i][j] + 2
        for c in range(26):
            successors = outgoing[j][c]
            if not successors:
                continue
            successor_mask = 0
            for b in successors:
                successor_mask |= 1 << b
            for a in incoming[i][c]:
                candidates = successor_mask & unvisited[a]
                while candidates:
                    bit = candidates & -candidates
                    candidates -= bit
                    b = bit.bit_length() - 1
                    unvisited[a] ^= bit
                    dist[a][b] = new_dist
                    queue.append((a, b))

    sys.stdout.write('\n'.join(' '.join(map(str, row)) for row in dist))

if __name__ == '__main__':
    solve()

