import sys

def solve():
    d = list(map(int, sys.stdin.buffer.read().split()))
    if not d:
        return
    n, m = d[0], d[1]
    rows = [0] * n
    p = 2
    for _ in range(m):
        u, v = d[p] - 1, d[p + 1] - 1
        p += 2
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    a = rows[:]
    pivots = []
    r = 0
    for c in range(n):
        sel = next((i for i in range(r, n) if (a[i] >> c) & 1), None)
        if sel is None:
            continue
        a[r], a[sel] = a[sel], a[r]
        for i in range(n):
            if i != r and ((a[i] >> c) & 1):
                a[i] ^= a[r]
        pivots.append(c)
        r += 1

    pivot_set = set(pivots)
    basis = []
    for f in range(n):
        if f not in pivot_set:
            x = 1 << f
            for i, c in enumerate(pivots):
                if (a[i] >> f) & 1:
                    x |= 1 << c
            basis.append(x)

    labels = [0] * n
    for j, vec in enumerate(basis):
        for v in range(n):
            if (vec >> v) & 1:
                labels[v] |= 1 << j

    if any(x == 0 for x in labels):
        print('No')
        return
    shift = 2 if n > 1 and max(labels) <= ((1 << 60) - 1) >> 2 else 0
    print('Yes')
    print(*(x << shift for x in labels))

solve()

