    disc = 12 * (N // d) - 3 * d * d
    if disc < 0:
        continue
    s = math.isqrt(disc)
    if s * s != disc:
        continue
    num = s - 3 * d
    if num > 0 and num % 6 == 0:
        y = num // 6
        print(y + d, y)
        break
