from typing import List
import math

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odd_count = (n + 1) // 2
        even_count = n // 2

        def parity_slots(length: int, first_parity: int):
            if length == 0:
                return (0, 0)
            a = (length + 1) // 2
            b = length // 2
            return (a, b) if first_parity == 1 else (b, a)

        total = 0
        for first in (1, 0):
            if parity_slots(n, first) == (odd_count, even_count):
                total += math.factorial(odd_count) * math.factorial(even_count)
        if k > total:
            return []

        available = list(range(1, n + 1))
        answer = []
        previous_parity = None

        for i in range(n):
            for value in available:
                parity = value % 2
                if previous_parity is not None and parity == previous_parity:
                    continue

                remaining = available.copy()
                remaining.remove(value)
                length = n - i - 1
                needed = parity_slots(length, 1 - parity) if length else (0, 0)
                remaining_odds = sum(x % 2 for x in remaining)
                remaining_evens = len(remaining) - remaining_odds

                count = 0
                if (remaining_odds, remaining_evens) == needed:
                    count = math.factorial(remaining_odds) * math.factorial(remaining_evens)

                if k > count:
                    k -= count
                else:
                    answer.append(value)
                    available = remaining
                    previous_parity = parity
                    break
            else:
                return []

        return answer

