class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        powers = [1 % k] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k

        coeff = []
        for i in range(m):
            if n % 2 and i == m - 1:
                coeff.append(powers[i])
            else:
                coeff.append((powers[i] + powers[n - 1 - i]) % k)

        # suffix[i] is a bitmask of all residues achievable by variables i onward.
        suffix = [0] * (m + 1)
        suffix[m] = 1
        for i in range(m - 1, -1, -1):
            old = suffix[i + 1]
            mask = 0
            for r in range(k):
                if old >> r & 1:
                    for d in range(10):
                        mask |= 1 << ((r + d * coeff[i]) % k)
            suffix[i] = mask

        digits = []
        rem = 0
        for i, c in enumerate(coeff):
            minimum = 1 if i == 0 else 0
            for d in range(9, minimum - 1, -1):
                need = (-(rem + d * c)) % k
                if suffix[i + 1] >> need & 1:
                    digits.append(str(d))
                    rem = (rem + d * c) % k
                    break

        half = ''.join(digits)
        return half + (half[:-1][::-1] if n % 2 else half[::-1])

