from typing import List
from bisect import bisect_right

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        size = 1
        while size < n:
            size <<= 1
        profiles = [None] * (2 * size)
        for i, x in enumerate(nums):
            profiles[size + i] = [x]
        for p in range(size - 1, 0, -1):
            a, b = profiles[p * 2], profiles[p * 2 + 1]
            if a is None:
                profiles[p] = b
            elif b is None:
                profiles[p] = a
            else:
                m = a[-1]
                # Prefix maxima of the combined segment
                profiles[p] = a + [max(m, x) for x in b]

        pref = [0]
        for x in nums:
            pref.append(pref[-1] + x)

        def cost(l, r):
            # Obtain canonical segment nodes in left-to-right order.
            L, R = l + size, r + size + 1
            left_nodes, right_nodes = [], []
            while L < R:
                if L & 1:
                    left_nodes.append(L)
                    L += 1
                if R & 1:
                    R -= 1
                    right_nodes.append(R)
                L >>= 1
                R >>= 1
            nodes = left_nodes + right_nodes[::-1]
            threshold = -1
            total_max = 0
            for node in nodes:
                arr = profiles[node]
                # arr is the prefix-maximum profile of this segment.
                j = bisect_right(arr, threshold)
                total_max += j * threshold + (sum(arr[j:]) if j < len(arr) else 0)
                threshold = max(threshold, arr[-1])
            return total_max - (pref[r + 1] - pref[l])

        ans = 0
        for l in range(n):
            lo, hi = l, n - 1
            while lo < hi:
                mid = (lo + hi + 1) // 2
                if cost(l, mid) <= k:
                    lo = mid
                else:
                    hi = mid - 1
            ans += lo - l + 1
        return ans

