class Solution:
    def makeStringGood(self, s: str) -> int:
        from collections import Counter
        cnt = Counter(s)
        a = [cnt.get(chr(97+i), 0) for i in range(26)]
        n = len(s)
        # The useful common frequencies are bounded by the largest existing
        # frequency: choosing a larger one cannot improve on deleting extras.
        candidates = set(a)
        candidates.discard(0)
        candidates.add(1)
        ans = n
        for k in candidates:
            # dp indexed by the number of characters carried from the previous
            # letter. At each letter, either retain the common frequency or
            # remove the letter; excess characters may be advanced one step.
            dp = {0: 0}
            for i, c in enumerate(a):
                nd = {}
                for carry, cost in dp.items():
                    total = c + carry
                    # Do not advance any characters.
                    for goal in (0, k):
                        v = cost + abs(total - goal)
                        if v < nd.get(0, n * 30):
                            nd[0] = v
                    # Advance the surplus to the next alphabet character.
                    if i < 25:
                        surplus = max(0, total - k)
                        if surplus:
                            v = cost + surplus + max(0, total-surplus-k)
                            if v < nd.get(surplus, n * 30):
                                nd[surplus] = v
                dp = nd
            ans = min(ans, min(dp.values()))
        return ans

