class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        g = [[] for _ in range(n)]
        for u,v,w in edges:
            g[u].append((v,w)); g[v].append((u,w))
        parent = [-1]*n
        pw = [0]*n
        order = [0]
        parent[0] = 0
