                if v != parent[u]:
                    parent[v] = u; pw[v] = w; order.append(v)
        d0 = [0]*n
        d1 = [0]*n
        for u in reversed(order):
            base = 0
            gains = []
            for v,w in g[u]:
                if parent[v] == u:
                    base += d0[v]
                    gains.append(w + d1[v] - d0[v])
            gains.sort(reverse=True)
            pref = [0]
            for x in gains:
