from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for v in range(1, n):
            children[parent[v]].append(v)

        # Iterative postorder traversal, visiting children in ascending order.
        postorder = []
        stack = [(0, False)]
        while stack:
            u, done = stack.pop()
            if done:
                postorder.append(u)
            else:
                stack.append((u, True))
                for v in reversed(children[u]):
                    stack.append((v, False))

        position = [0] * n
        text = [''] * n
        for i, u in enumerate(postorder):
            position[u] = i
            text[i] = s[u]

        # In postorder each child's size is known before its parent is processed.
        subtree_size = [1] * n
        for u in postorder:
            if u != 0:
                subtree_size[parent[u]] += subtree_size[u]

        # Manacher radii for odd-length palindromes.
        odd = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - k >= 0 and i + k < n and text[i - k] == text[i + k]:
                k += 1
            odd[i] = k
            if i + k - 1 > right:
                left, right = i - k + 1, i + k - 1

        # Manacher radii for even-length palindromes; even[i] is centered
        # between positions i-1 and i.
        even = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
