class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        min_prefix = [None] * k
        min_prefix[0] = 0
        prefix = 0
        best = -10**30

        for end, value in enumerate(nums, 1):
            prefix += value
            residue = end % k

            # Equal prefix-index residues mean the subarray length is divisible by k.
            if min_prefix[residue] is not None:
                best = max(best, prefix - min_prefix[residue])

            if min_prefix[residue] is None or prefix < min_prefix[residue]:
                min_prefix[residue] = prefix

        return best

