                z[k] += 1
            if k + z[k] - 1 > right:
                left, right = k, k + z[k] - 1

        answer = 0
        for i in range(1, n - 1):
            max_distance = n - i - 1
            if z[i] >= i:
                # Every possible second split point works in this case.
                answer += max_distance
                continue

            # For fixed start i of the second part, Z values on nums[i:]
            # test whether nums[i:i+d] is a prefix of nums[i+d:].
            suffix = nums[i:]
            m = len(suffix)
            local_z = [0] * m
            l = r = 0
            for d in range(1, max_distance + 1):
                if d <= r:
