from typing import List

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n = len(source)
        m = len(pattern)
        removable = bytearray(n)
        for i in targetIndices:
            removable[i] = 1

        # dp[j] is the maximum number of target characters deleted so far
        # while matching the first j characters of pattern.
        dp = [-1] * (m + 1)
        dp[0] = 0

        for i, ch in enumerate(source):
            ndp = [v + removable[i] if v >= 0 else -1 for v in dp]
            for j in range(m):
                if dp[j] >= 0 and ch == pattern[j] and dp[j] > ndp[j + 1]:
                    ndp[j + 1] = dp[j]
            dp = ndp

        return dp[m]

