class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        t = '1' + s + '1'
        runs = []
        ch = t[0]
        cnt = 1
        for c in t[1:]:
            if c == ch:
                cnt += 1
            else:
                runs.append((ch, cnt))
                ch, cnt = c, 1
        runs.append((ch, cnt))

        best_gain = 0
        for i in range(1, len(runs) - 1):
            if runs[i][0] == '1':
                # Removing this run merges its neighboring zero runs;
                # turning that merged run to ones gains the two zero lengths.
                best_gain = max(best_gain, runs[i - 1][1] + runs[i + 1][1])

        return s.count('1') + best_gain

